CHART_COLORS = ["#f43f7a", "#ffb000", "#20bf75", "#2d9cdb", "#8b5cf6", "#00b8c8"]

def chart_layout(fig, height=340):
    fig.update_layout(
        height=height, paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(255,255,255,0.55)",
        font=dict(color="#17315d", family="Arial", size=12),
        margin=dict(l=18, r=18, t=42, b=18), legend=dict(orientation="h", y=-0.18),
        title_font=dict(size=17, color="#17366f"),
    )
    fig.update_xaxes(showgrid=False, linecolor="#e9d9ad")
    fig.update_yaxes(gridcolor="rgba(180,150,90,.18)", zerolinecolor="#e9d9ad")
    return fig

BASE_DIR = Path(__file__).resolve().parent
DATA_PATH = BASE_DIR / "employee_data.csv"
MODEL_PATH = BASE_DIR / "employee_attrition_model.joblib"

# The feature engineering below must remain consistent with the model
# trained in the project notebook.
FEATURE_COLUMNS = [
    "Age", "BusinessTravel", "DailyRate", "Department", "DistanceFromHome",
    "Education", "EducationField", "EnvironmentSatisfaction", "Gender",
    "HourlyRate", "JobInvolvement", "JobLevel", "JobRole", "JobSatisfaction",
    "MaritalStatus", "MonthlyIncome", "MonthlyRate", "NumCompaniesWorked",
    "OverTime", "PercentSalaryHike", "PerformanceRating",
    "RelationshipSatisfaction", "StockOptionLevel", "TotalWorkingYears",
    "TrainingTimesLastYear", "WorkLifeBalance", "YearsAtCompany",
    "YearsInCurrentRole", "YearsSinceLastPromotion", "YearsWithCurrManager",
    "IncomeExperienceRatio", "PromotionDelay", "EngagementScore",
    "WorkloadStress",
]

RISK_ORDER = ["Low Risk", "Medium Risk", "High Risk"]


@st.cache_resource(show_spinner=False)
def load_model_bundle(path_string):
    return joblib.load(path_string)


@st.cache_data(show_spinner=False)
def load_dataset(path_string, modified_time):
    return pd.read_csv(path_string)


def engineer_features(data):
    """Recreate the four engineered features used during model training."""
    result = data.copy()

    required = [
        "MonthlyIncome", "TotalWorkingYears", "YearsSinceLastPromotion",
        "JobInvolvement", "JobSatisfaction", "EnvironmentSatisfaction",
        "RelationshipSatisfaction", "WorkLifeBalance", "OverTime",
    ]
    missing = [column for column in required if column not in result.columns]
    if missing:
        raise ValueError(f"Dataset is missing required feature columns: {missing}")

    result["IncomeExperienceRatio"] = (
        pd.to_numeric(result["MonthlyIncome"], errors="coerce")
        / (pd.to_numeric(result["TotalWorkingYears"], errors="coerce") + 1)
    )
    result["PromotionDelay"] = (
        pd.to_numeric(result["YearsSinceLastPromotion"], errors="coerce") >= 3
    ).astype(int)

    engagement_columns = [
        "JobInvolvement",
        "JobSatisfaction",
        "EnvironmentSatisfaction",
        "RelationshipSatisfaction",
        "WorkLifeBalance",
    ]
    result["EngagementScore"] = result[engagement_columns].apply(
        pd.to_numeric, errors="coerce"
    ).mean(axis=1)

    result["WorkloadStress"] = (
        result["OverTime"].astype(str).str.strip().str.lower().eq("yes")
        & (pd.to_numeric(result["WorkLifeBalance"], errors="coerce") <= 2)
    ).astype(int)

    return result


def assign_risk(probability):
    if probability < 0.30:
        return "Low Risk"
    if probability <= 0.60:
        return "Medium Risk"
    return "High Risk"


def get_feature_names(preprocessor):
    try:
        return np.asarray(preprocessor.get_feature_names_out(), dtype=str)
    except Exception:
        return np.asarray(
            [f"Transformed feature {i + 1}" for i in range(len(bundle["model"].coef_[0]))],
            dtype=str,
        )


def explain_feature_name(feature_name):
    """Convert transformed feature names into readable labels."""
    name = str(feature_name)
    for prefix in ("num__", "cat__"):
        name = name.replace(prefix, "")
    name = name.replace("_", " ").strip()
    mapping = {
        "OverTime Yes": "Overtime: Yes", "OverTime No": "Overtime: No",
        "BusinessTravel Travel Frequently": "Frequent business travel",
        "BusinessTravel Travel Rarely": "Occasional business travel",
        "BusinessTravel Non Travel": "No business travel",
        "WorkLifeBalance": "Work-life balance", "JobSatisfaction": "Job satisfaction",
        "EnvironmentSatisfaction": "Environment satisfaction",
        "RelationshipSatisfaction": "Relationship satisfaction", "JobInvolvement": "Job involvement",
        "YearsSinceLastPromotion": "Years since last promotion", "YearsAtCompany": "Years at company",
        "YearsInCurrentRole": "Years in current role", "YearsWithCurrManager": "Years with current manager",
        "MonthlyIncome": "Monthly income", "IncomeExperienceRatio": "Income relative to experience",
        "PromotionDelay": "Promotion delay indicator", "EngagementScore": "Engagement composite score",
        "WorkloadStress": "Workload stress indicator",
    }
    return mapping.get(name, name)


